module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    assign A_greater = (A > B);
    assign A_equal = (A == B);
    assign A_less = (A < B);

endmodule

module div_16bit (
    input wire [15:0] A,
    input wire [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    always @(*) begin
        if (B == 0) begin
            result = 0;
            odd = A;
        end else begin
            result = A / B;
            odd = A % B;
        end
    end

endmodule

module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

    assign {overflow, result} = $signed(A) - $signed(B);

endmodule

module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

    integer i;

    always @(*) begin
        product = 16'b0;  

        for (i = 0; i < 8; i = i + 1) begin

            if (B[i] == 1'b1) begin
                product = product + (A << i);
            end
        end
    end

endmodule

module fixed_point_adder #(
    parameter Q = 15,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = a + b;
        end else begin

            if (a >= b) begin
                res = a - b;
            end else begin
                res = b - a;
            end
        end
    end

    assign c = res;

endmodule

module width_8to16 (
    input 				   clk,
    input 				   rst_n,
    input				      valid_in,
    input	   [7:0]		   data_in,
    output	reg			valid_out,
    output   reg [15:0]	data_out
);

    reg [7:0] data_lock;
    reg flag;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'b0;
            data_lock <= 8'b0;
            flag <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            if (valid_in && !flag) begin
                data_lock <= data_in;
                flag <= 1'b1;
            end else if (valid_in && flag) begin
                data_out <= {data_lock, data_in};
                flag <= 1'b0;
                valid_out <= 1'b1;
            end
        end
    end

endmodule

module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);

    reg [4:0] i;
    reg [15:0] areg;
    reg [15:0] breg;
    reg [31:0] yout_r;
    reg done_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'd0;
            areg <= 16'd0;
            breg <= 16'd0;
            yout_r <= 32'd0;
            done_r <= 1'b0;
        end else begin
            if (start) begin
                if (i == 5'd0) begin
                    areg <= ain;
                    breg <= bin;
                end else if (i < 5'd17) begin
                    if (areg[i-1]) begin
                        yout_r <= yout_r + (breg << (i-1));
                    end
                end
                i <= i + 5'd1;
            end else begin
                i <= 5'd0;
            end
            if (i == 5'd16) begin
                done_r <= 1'b1;
            end else begin
                done_r <= 1'b0;
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;

endmodule

module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

    reg a_prev;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_prev <= 0;
            rise <= 0;
            down <= 0;
        end else begin
            a_prev <= a;
            if (a_prev == 0 && a == 1) begin
                rise <= 1;
                down <= 0;
            end else if (a_prev == 1 && a == 0) begin
                rise <= 0;
                down <= 1;
            end else begin
                rise <= 0;
                down <= 0;
            end
        end
    end

endmodule

module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

reg [5:0] cnt_50;
reg [3:0] cnt_10;
reg [6:0] cnt_1;

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        CLK_50 <= 0;
        CLK_10 <= 0;
        CLK_1 <= 0;
        cnt_50 <= 0;
        cnt_10 <= 0;
        cnt_1 <= 0;
    end else begin

        CLK_50 <= ~CLK_50;

        if (cnt_10 == 4) begin
            CLK_10 <= ~CLK_10;
            cnt_10 <= 0;
        end else begin
            cnt_10 <= cnt_10 + 1;
        end

        if (cnt_1 == 49) begin
            CLK_1 <= ~CLK_1;
            cnt_1 <= 0;
        end else begin
            cnt_1 <= cnt_1 + 1;
        end
    end
end

endmodule

