module fixed_point_subtractor #(
	parameter Q = 15,
	parameter N = 32
	)
	(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
    );

reg [N-1:0] res;

assign c = res;

always @(a,b) begin

	if(a[N-1] == b[N-1]) begin					
		res[N-2:0] = a[N-2:0] - b[N-2:0];		
		res[N-1] = a[N-1];							


		end												

	else if(a[N-1] == 0 && b[N-1] == 1) begin		
		if( a[N-2:0] > b[N-2:0] ) begin					
			res[N-2:0] = a[N-2:0] + b[N-2:0];			
			res[N-1] = 0;										
			end
		else begin												
			res[N-2:0] = b[N-2:0] + a[N-2:0];		
			if (res[N-2:0] == 0)
				res[N-1] = 0;									
			else
				res[N-1] = 1;									
			end
		end
	else begin												
		if( a[N-2:0] > b[N-2:0] ) begin					
			res[N-2:0] = a[N-2:0] + b[N-2:0];			
			if (res[N-2:0] == 0)
				res[N-1] = 0;										
			else
				res[N-1] = 1;										
			end
		else begin												
			res[N-2:0] = b[N-2:0] + a[N-2:0];			
			res[N-1] = 0;										
			end
		end
	end
endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output reg [15:0] y,
    output reg Co
);

    wire [7:0] sum_low;
    wire Cout_low;

    adder_8bit low_adder (
        .a(a[7:0]),
        .b(b[7:0]),
        .cin(Cin),
        .sum(sum_low),
        .co(Cout_low)
    );

    wire [7:0] sum_high;
    wire Cout_high;

    adder_8bit high_adder (
        .a(a[15:8]),
        .b(b[15:8]),
        .cin(Cout_low),
        .sum(sum_high),
        .co(Cout_high)
    );

    assign y = {sum_high, sum_low};
    assign Co = Cout_high;

endmodule

