module add1 (
    input wire a,
    input wire b,
    input wire Cin,
    output wire y,
    output wire Co
);
    assign y = ((~a) & (~b) & Cin | (~a) & b & (~Cin) | a & (~b) & (~Cin) | (a & b & Cin));
    assign Co = ((~a & b & Cin) | (a & ~b & Cin) | (a & b & ~Cin) | (a & b & Cin));

endmodule

module counter_12 (
    input rst_n,
    input clk,
    input valid_count,
    output reg [3:0] out
);
    parameter MAX_COUNT = 4'd11;

    reg [3:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= 4'b0000;
        end else if (valid_count) begin
            if (count_reg == MAX_COUNT) begin
                count_reg <= 4'b0000;
            end else begin
                count_reg <= count_reg + 1;
            end
        end
    end

    assign out = count_reg;
endmodule

module calendar (
    input CLK,
    input RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            Secs <= 6'd0;
            Mins <= 6'd0;
            Hours <= 6'd0;
        end else begin
            if (Secs == 6'd59) begin
                Secs <= 6'd0;
                if (Mins == 6'd59) begin
                    Mins <= 6'd0;
                    if (Hours == 6'd23) begin
                        Hours <= 6'd0;
                    end else begin
                        Hours <= Hours + 1;
                    end
                end else begin
                    Mins <= Mins + 1;
                end
            end else begin
                Secs <= Secs + 1;
            end
        end
    end

endmodule

module adder_bcd (
    input  [3:0] A,
    input  [3:0] B,
    input  Cin,
    output reg [3:0] Sum,
    output reg Cout
);

reg [4:0] sum_int;

always @(*) begin
    sum_int = A + B + Cin;
    if (sum_int > 9) begin
        Sum = sum_int - 10;
        Cout = 1;
    end else begin
        Sum = sum_int;
        Cout = 0;
    end
end

endmodule

