module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

parameter IDLE = s0;
parameter DETECTING_1 = s1;
parameter DETECTING_2 = s2;
parameter PULSE_END = s3;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in == 1'b1) state <= DETECTING_1; else state <= IDLE;
            end
            DETECTING_1: begin
                if (data_in == 1'b0) state <= DETECTING_2; else state <= DETECTING_1;
            end
            DETECTING_2: begin
                if (data_in == 1'b1) state <= PULSE_END; else state <= DETECTING_2;
            end
            PULSE_END: begin
                data_out <= 1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

