    wire match_s2 = (current_state == 3'b010 && data_in == 1'b0);
    wire match_s3 = (current_state == 3'b100 && data_in == 1'b1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= 3'b000; 
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = 3'b000; 
        case (current_state)
            3'b000: 
                if (data_in == 1'b1) begin
                    next_state = 3'b001; 
                end
            3'b001: 
                if (data_in == 1'b0) begin
                    next_state = 3'b010; 
                end
            3'b010: 
                if (data_in == 1'b0) begin
                    next_state = 3'b100; 
                end
            3'b100: 
