endmodule

module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

    parameter IDLE = 2'b00;
    parameter ADD = 2'b01;
    parameter RESULT = 2'b10;

    reg [1:0] current_state;
    reg [1:0] next_state;
    reg [63:0] pipe_adda;
    reg [63:0] pipe_addb;
    reg [63:0] pipe_carry_in;
    reg [64:0] pipe_sum;
    wire [64:0] sum;
    wire [63:0] carry_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        case (current_state)
            IDLE: begin
                if (i_en) begin
                    next_state = ADD;
                end else begin
                    next_state = IDLE;
                end
            end
            ADD: begin
                next_state = RESULT;
            end
            RESULT: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_adda <= 64'b0;
            pipe_addb <= 64'b0;
            pipe_carry_in <= 1'b0;
        end else begin
            if (current_state == IDLE && i_en) begin
                pipe_adda <= adda;
                pipe_addb <= addb;
                pipe_carry_in <= 1'b0;
            end
        end
    end

    assign sum = $unsigned(pipe_adda) + $unsigned(pipe_addb) + pipe_carry_in;

    generate
        genvar i;
        for (i = 0; i < 64; i = i + 1) begin : adders
            assign carry_out[i] = |(sum[i+1:i]);
        end
    endgenerate

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_sum <= 65'b0;
        end else begin
            if (current_state == RESULT) begin
                pipe_sum <= {carry_out, sum};
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_en <= 1'b0;
        end else begin
            if (current_state == RESULT) begin
                o_en <= 1'b1;
            end else begin
                o_en <= 1'b0;
            end
        end
    end

    assign result = pipe_sum;

endmodule

