        s2_ff1 <= 'd0;
        s2_ff2 <= 'd0;
        s3_ff1 <= 'd0;
    end
    else begin
        s1_ff1 <= s1;
        s1_ff2 <= s1_ff1;
        s1_ff3 <= s1_ff2;
        s2_ff1 <= s2;
        s2_ff2 <= s2_ff1;
        s3_ff1 <= s3;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c1 <= 1'b0;
        s1 <= 'd0;
    end
    else if (i_en) begin
        {c1, s1} <= a1 + b1;
    end
    else begin
        c1 <= c1;
        s1 <= s1;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c2 <= 1'b0;
        s2 <= 'd0;
    end
    else if (stage1) begin
        {c2, s2} <= a2_ff1 + b2_ff1 + c1;
    end
    else begin
        c2 <= c2;
        s2 <= s2;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c3 <= 1'b0;
        s3 <= 'd0;
    end
    else if (stage2) begin
        {c3, s3} <= a3_ff2 + b3_ff2 + c2;
    end
    else begin
        c3 <= c3;
        s3 <= s3;
    end
end

always @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
        c4 <= 1'b0;
        s4 <= 'd0;
    end
    else if (stage3) begin
        {c4, s4} <= a4_ff3 + b4_ff3 + c3;
    end
    else begin
        c4 <= c4;
        s4 <= s4;
    end
end

assign result = {c4, s4, s3_ff1, s2_ff2, s1_ff3};

endmodule

module traffic_light #(
    parameter idle = 2'd0,
    parameter s1_red = 2'd1,
    parameter s2_yellow = 2'd2,
    parameter s3_green = 2'd3
) (
    input rst_n,
    input clk,
    input pass_request,
    output wire[7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd0;
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                end
                s1_red: begin
                    red <= 1'b1;
                    if (cnt == 8'd3) begin
                        state <= s3_green;
                    end
                end
                s2_yellow: begin
                    yellow <= 1'b1;
                    if (cnt == 8'd3) begin
                        state <= s1_red;
                    end
                end
                s3_green: begin
                    green <= 1'b1;
                    if (cnt == 8'd3) begin
                        state <= s2_yellow;
                    end
                end
                default: begin
                    state <= idle;
                end
            endcase
            if (pass_request && green && cnt > 8'd10) begin
                cnt <= 8'd10;
            end else begin
                if (cnt != 8'd0) begin
                    cnt <= cnt - 8'd1;
                end
            end
        end
    end

    assign clock = cnt;

endmodule

module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] sr;
    reg [3:0] cnt;
    reg [3:0] start_cnt;
    reg [7:0] neg_divisor;
    reg [7:0] temp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 0;
            sr <= 0;
            cnt <= 0;
            start_cnt <= 0;
            neg_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                abs_dividend <= (sign && dividend[7]) ? ~dividend + 1 : dividend;
                abs_divisor <= (sign && divisor[7]) ? ~divisor + 1 : divisor;
                sr <= {abs_dividend, 1'b0};
                neg_divisor <= ~abs_divisor + 1;
                cnt <= 4'd0;
                start_cnt <= 4'd1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin
                    cnt <= 4'd0;
                    start_cnt <= 4'd0;
                    result <= {sr[7:0], sr[15:8]};
                end else begin
                    cnt <= cnt + 4'd1;
                    temp <= sr - neg_divisor;
                    if (temp[8]) begin
                        sr <= {temp[7:0], 1'b0};
                    end else begin
                        sr <= {temp[7:0], 1'b1};
                    end
                end
            end
        end
    end

endmodule

module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [9:0] sum;
reg [2:0] count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'b0;
        count <= 3'b0;
        valid_out <= 1'b0;
    end else begin
        if (valid_in) begin
            sum <= sum + data_in;
            count <= count + 1;
        end
        if (count == 3'b111) begin
            data_out <= sum;
            valid_out <= 1'b1;
            count <= 3'b0;
        end else begin
            valid_out <= 1'b0;
        end
    end
end

endmodule

module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg [49:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        counter <= 3'b000;
        a_mantissa <= 24'b0;
        b_mantissa <= 24'b0;
        z_mantissa <= 24'b0;
        a_exponent <= 10'b0;
        b_exponent <= 10'b0;
        z_exponent <= 10'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        z_sign <= 1'b0;
        product <= 50'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= {a[22:0], 1'b1}; 
                b_mantissa <= {b[22:0], 1'b1}; 
            end
            3'b001: begin 
                if ((a_exponent == 10'hFF && a_mantissa != 24'b0) || (b_exponent == 10'hFF && b_mantissa != 24'b0)) begin
                    z <= (a_sign ^ b_sign) ? 32'hFFFFFFFF : 32'h7FFFFFFF; 
                end else begin
                    counter <= 3'b010;
                end
            end
            3'b010: begin 
                product <= $signed(a_mantissa) * $signed(b_mantissa);
                z_exponent <= a_exponent + b_exponent - 127;
                z_mantissa <= product[48:25];
                guard_bit <= product[24];
                round_bit <= product[23];
                sticky <= |product[22:0];
            end
            3'b011: begin 
                if (round_bit && (sticky || guard_bit)) begin
                    z_mantissa <= z_mantissa + 1;
                end
                if (z_mantissa >= 256) begin
                    z_mantissa <= z_mantissa >> 1;
                    z_exponent <= z_exponent + 1;
                end
            end
            3'b100: begin 
                z <= {z_sign, z_exponent, z_mantissa};
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);

reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH-1:0] wptr, rptr;
reg [ADDR_WIDTH-1:0] wptr_buff, rptr_buff;
wire [ADDR_WIDTH-1:0] wptr_syn, rptr_syn;

dual_port_RAM #(.WIDTH(WIDTH), .DEPTH(DEPTH)) dual_port_ram (
    .wclk(wclk),
    .wenc(winc),
    .ren(rinc),  
    .waddr(waddr_bin),
    .raddr(raddr_bin),
    .wdata(wdata),
    .rdata(rdata)
);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= (waddr_bin + 1) % DEPTH;
        wptr <= (wptr + 1) % DEPTH;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= (raddr_bin + 1) % DEPTH;
        rptr <= (rptr + 1) % DEPTH;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end

assign wfull = (wptr == {~rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
assign rempty = (rptr == wptr_syn);

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input rclk,
    input wenc,
    input ren,
    input [$clog2(DEPTH)-1:0] waddr,
    input [$clog2(DEPTH)-1:0] raddr,
    input [WIDTH-1:0] wdata,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    rdata <= RAM_MEM[raddr];
end

endmodule

module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
        cnt <= 4'b0;
    end else begin
        if (din_valid) begin
            dout_parallel[cnt] <= din_serial;
            cnt <= cnt + 1;
            if (cnt == 4'b1111) begin
                dout_valid <= 1'b1;
            end else begin
                dout_valid <= 1'b0;
            end
        end else begin
            if (cnt == 4'b1111) begin
                dout_valid <= 1'b0;
            end
        end
    end
end

endmodule
